async function runCase(name, payload, assert) {
  const root = path.resolve(__dirname, '..');
  const actions = buildRuntimeActions({ config: { root }, payload: { action: 'simulateRuntime', origin: 'http://localhost:8080', url: 'http://localhost:8080', timeoutMs: 60000, ...payload } });
  const started = Date.now();
  const result = await actions.simulateRuntime();
  const durationMs = Date.now() - started;
  const passed = await assert(result);
  return { name, ok: !!passed, durationMs, result: compact(result) };
}

function compact(result) {
  return {
    ok: result?.ok !== false,
    runtime: result?.runtime,
    entry: result?.entry,
    errors: Array.isArray(result?.errors) ? result.errors.slice(0, 4) : result?.errors,
    console: Array.isArray(result?.console) ? result.console.slice(0, 6) : result?.console,
