    assetGraphSize: result?.assetGraph?.nodes?.length || result?.assetGraph?.length || 0,
    keys: result ? Object.keys(result).slice(0, 18) : []
  };
}

function files64(files) { return Buffer.from(JSON.stringify(files), 'utf8').toString('base64'); }

function manyModuleFiles(count = 64) {
  const files = {};
  for (let i = 0; i < count; i++) {
    const next = i + 1 < count ? `import { v as n } from './m${i + 1}.js';\n` : 'const n = 0;\n';
    files[`m${i}.js`] = `${next}export const v = n + ${i + 1};`;
  }
  files['index.js'] = "import { v } from './m0.js'; console.log('large-graph', v); globalThis.__stressLarge = v;";
  return files;
}

